import { createContext, useCallback, useContext, useEffect, useRef, useState, type ReactNode } from 'react'
import { addToast, dismissToast, toastAnnouncement, type ToastItem, type ToastOptions } from './toastStack'
import { cx } from './ui'

export type { ToastOptions }

const ToastContext = createContext<(toast: ToastOptions) => void>(() => {})

export const useToast = () => useContext(ToastContext)

const TONE: Record<ToastItem['tone'], { icon: string; className: string }> = {
  ok: { icon: '✓', className: 'border-emerald-400/40 text-emerald-300' },
  bad: { icon: '✕', className: 'border-rose-400/50 text-rose-300' },
  info: { icon: 'i', className: 'border-indigo-400/40 text-indigo-300' },
}

/** Runs fn now, or once the currently open modal dialog closes (toasts behind a modal would be missed). */
function whenNoModal(fn: () => void) {
  const modal = document.querySelector<HTMLDialogElement>('dialog:modal')
  if (!modal) return fn()
  modal.addEventListener('close', () => setTimeout(() => whenNoModal(fn), 0), { once: true })
}

type AriaNotify = (message: string, options?: { priority?: 'normal' | 'high' }) => void

export function ToastProvider({ children }: { children: ReactNode }) {
  const [stack, setStack] = useState<ToastItem[]>([])
  const [polite, setPolite] = useState('')
  const [assertive, setAssertive] = useState('')
  const regionRef = useRef<HTMLElement>(null)
  const nextId = useRef(1)
  const lastOutsideFocus = useRef<HTMLElement | null>(null)

  const announce = useCallback((item: ToastItem) => {
    const text = toastAnnouncement(item)
    const notify = (document as Document & { ariaNotify?: AriaNotify }).ariaNotify
    if (typeof notify === 'function') {
      notify.call(document, text, { priority: item.tone === 'bad' ? 'high' : 'normal' })
      return
    }
    // Fallback: the live regions exist from page load; clear then set (after a short delay so focus moves
    // and other speech do not swallow it, and so repeating the same text is announced again).
    const set = item.tone === 'bad' ? setAssertive : setPolite
    set('')
    setTimeout(() => set(text), 150)
  }, [])

  const show = useCallback(
    (toast: ToastOptions) =>
      whenNoModal(() => {
        const id = nextId.current++
        setStack((s) => addToast(s, toast, id))
        announce(addToast([], toast, id)[0])
      }),
    [announce],
  )

  // Remember where focus was outside the toasts, to return there when the last focused toast is dismissed.
  useEffect(() => {
    const onFocus = (e: FocusEvent) => {
      if (e.target instanceof HTMLElement && !regionRef.current?.contains(e.target)) lastOutsideFocus.current = e.target
    }
    document.addEventListener('focusin', onFocus)
    return () => document.removeEventListener('focusin', onFocus)
  }, [])

  // The region is a manual popover (top layer, no light dismiss) while it has toasts.
  useEffect(() => {
    const region = regionRef.current as (HTMLElement & { showPopover?: () => void; hidePopover?: () => void }) | null
    if (!region || typeof region.showPopover !== 'function') return
    const open = region.matches(':popover-open')
    if (stack.length && !open) region.showPopover()
    else if (!stack.length && open) region.hidePopover?.()
  }, [stack.length])

  const dismiss = (id: number) => {
    const region = regionRef.current
    const hadFocus = !!region && region.querySelector(`[data-toast-id="${id}"]`)?.contains(document.activeElement)
    const index = stack.findIndex((t) => t.id === id)
    const rest = dismissToast(stack, id)
    setStack((s) => dismissToast(s, id))
    if (!hadFocus) return
    const next = rest[Math.min(index, rest.length - 1)]
    requestAnimationFrame(() => {
      const target = next ? region?.querySelector<HTMLElement>(`[data-toast-id="${next.id}"] [data-toast-close]`) : null
      const back = lastOutsideFocus.current?.isConnected ? lastOutsideFocus.current : null
      ;(target ?? back ?? document.body).focus()
    })
  }

  return (
    <ToastContext.Provider value={show}>
      {children}
      {/* Fallback announcers for browsers without ariaNotify (present from load so they are registered). */}
      <div className="sr-only">
        <p>Hlásenia aplikácie</p>
        <div aria-live="polite" aria-atomic="true">
          {polite}
        </div>
        <div aria-live="assertive" aria-atomic="true">
          {assertive}
        </div>
      </div>
      <section
        ref={regionRef}
        aria-label="Oznámenia"
        {...({ popover: 'manual' } as Record<string, string>)}
        className={cx('toast-region', !stack.length && 'hidden')}
      >
        <ol className="grid gap-2">
          {stack.map((t) => (
            <Toast key={t.id} toast={t} onDismiss={() => dismiss(t.id)} />
          ))}
        </ol>
      </section>
    </ToastContext.Provider>
  )
}

function Toast({ toast, onDismiss }: { toast: ToastItem; onDismiss: () => void }) {
  const [hovered, setHovered] = useState(false)
  const [focused, setFocused] = useState(false)
  const tone = TONE[toast.tone]

  useEffect(() => {
    if (toast.duration === null || hovered || focused) return
    const timer = setTimeout(onDismiss, toast.duration)
    return () => clearTimeout(timer)
    // onDismiss changes every render; the timer restarts only when its inputs do.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [toast.duration, hovered, focused])

  return (
    <li
      data-toast-id={toast.id}
      onPointerEnter={() => setHovered(true)}
      onPointerLeave={() => setHovered(false)}
      onFocus={() => setFocused(true)}
      onBlur={(e) => {
        if (!e.currentTarget.contains(e.relatedTarget as Node | null)) setFocused(false)
      }}
      className={cx('toast-item flex items-start gap-3 rounded-xl border bg-surface px-4 py-3 text-sm shadow-xl', tone.className)}
    >
      <span aria-hidden="true" className="mt-px w-4 shrink-0 text-center font-bold">
        {tone.icon}
      </span>
      <div className="min-w-0 flex-1 [overflow-wrap:anywhere]">
        <div className="font-medium text-zinc-100">
          {toast.tone === 'bad' && <span className="sr-only">Chyba: </span>}
          {toast.title}
        </div>
        {toast.description && <div className="mt-0.5 text-zinc-300">{toast.description}</div>}
        {toast.actionLabel && toast.onAction && (
          <button
            type="button"
            onClick={() => {
              toast.onAction?.()
              onDismiss()
            }}
            className="mt-2 rounded-full border border-white/15 px-3 py-1 text-xs text-zinc-100 hover:bg-white/10 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-indigo-400"
          >
            {toast.actionLabel}
          </button>
        )}
      </div>
      <button
        type="button"
        data-toast-close
        onClick={onDismiss}
        aria-label={`Zavrieť oznámenie: ${toast.title}`}
        className="-m-1 shrink-0 rounded-md p-1 text-zinc-400 hover:bg-white/10 hover:text-zinc-100 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-indigo-400"
      >
        <span aria-hidden="true">✕</span>
      </button>
    </li>
  )
}
